    static_assert(LEN_ARRAY(pkmn_animation_table) == PKMN_ANIM_COUNT);

    config_animation_entry_t get_config_animation_name_pkmn(size_t index) {
        assert(index < PKMN_ANIM_COUNT);
        const auto& entry = pkmn_animation_table[index];
        return { PKMN_STRINGS + entry.name, PKMN_STRINGS + entry.id, PKMN_STRINGS + entry.fqid, PKMN_STRINGS + entry.fqname, entry.anim_index, entry.set, entry.layout };
    }

    int config_parse_animation_name_pkmn(config::config_t& config, const char *value) {
        int ret = -1;
        for (size_t i = 0;ret < 0 && i < PKMN_ANIM_COUNT;++i) {
            const auto& entry = pkmn_animation_table[i];
            if (strcmp(value, PKMN_STRINGS + entry.name) == 0 ||
                strcmp(value, PKMN_STRINGS + entry.id) == 0 ||
                strcmp(value, PKMN_STRINGS + entry.fqid) == 0 ||
                strcmp(value, PKMN_STRINGS + entry.fqname) == 0) {
                config.animation_index = entry.anim_index;
                config.animation_dm_set = entry.set;
                config.animation_sprite_sheet_layout = entry.layout;
                ret = entry.anim_index;
                break;
            }
        }
        return ret;
    }
